package cl.dynasty.nexusbeacon.platform.classic;
import java.util.ArrayList;import java.util.Collections;import java.util.List;import org.bukkit.Material;import org.bukkit.configuration.ConfigurationSection;import cl.dynasty.nexusbeacon.platform.api.MaterialContext;import cl.dynasty.nexusbeacon.platform.api.MaterialResolution;
public final class ClassicEffectCatalog {
 public static final class Definition {private final String id;private final Material icon;Definition(String id,Material icon){this.id=id;this.icon=icon;}public String getId(){return id;}public Material getIcon(){return icon;}}
 private final List<Definition> definitions;private final List<String> supported;private final List<String> deferred;
 public ClassicEffectCatalog(ConfigurationSection effects,ClassicMaterialResolver materials,ClassicPotionEffectResolver potions){List<Definition>f=new ArrayList<Definition>();List<String>s=new ArrayList<String>();List<String>d=new ArrayList<String>();if(effects!=null)for(String id:effects.getKeys(false)){ConfigurationSection e=effects.getConfigurationSection(id);if(e==null||!e.getBoolean("enabled",true))continue;String type=e.getString("type","");MaterialResolution icon=materials.resolveMaterial(e.getString("icon"),MaterialContext.EFFECT_ICON);boolean semantic=!"POTION".equalsIgnoreCase(type)||potions.resolvePotionEffect(e.getString("potion")).isResolved();if(icon.isResolved()&&semantic){f.add(new Definition(id,icon.getMaterial().get()));s.add(id);}d.add(id);}definitions=Collections.unmodifiableList(f);supported=Collections.unmodifiableList(s);deferred=Collections.unmodifiableList(d);}
 public List<Definition> getDefinitions(){return definitions;}public List<String> getSupportedDefinitions(){return supported;}public List<String> getDeferredExecutors(){return deferred;}}
